using System.Diagnostics.CodeAnalysis;
using System.Text.Json.Serialization;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Identifies a pub/sub topic by its Dapr component and topic names. The backing
/// resource materializes only when a component uses the reference.
/// </summary>
public abstract record TopicRef
{
    /// <summary>The Dapr pubsub component name (DNS-1123 subdomain).</summary>
    public string PubSubName { get; }

    /// <summary>The topic name within the pubsub (DNS-1123 subdomain).</summary>
    public string TopicName { get; }

    /// <summary>The event contract type carried on the topic.</summary>
    public abstract Type ContractType { get; }

    private protected TopicRef(string pubSubName, string topicName)
    {
        PubSubName = NameRules.RequireSubdomain(pubSubName, nameof(pubSubName));
        TopicName = NameRules.RequireSubdomain(topicName, nameof(topicName));
    }
}

/// <summary>
/// A <see cref="TopicRef"/> whose generic argument identifies the event contract. Topology
/// wiring uses the topic names, while <see cref="TopicRef.ContractType"/> exposes the type.
/// </summary>
/// <typeparam name="T">The event contract type published on the topic.</typeparam>
public sealed record TopicRef<T> : TopicRef
{
    /// <inheritdoc />
    public override Type ContractType => typeof(T);

    private TopicRef(string pubSubName, string topicName)
        : base(pubSubName, topicName)
    {
    }

    /// <summary>Declares a topic on a pubsub component.</summary>
    /// <param name="pubSubName">The Dapr pubsub component name (DNS-1123 subdomain).</param>
    /// <param name="topicName">The topic name (DNS-1123 subdomain).</param>
    /// <exception cref="ArgumentException">A name is not a valid DNS-1123 subdomain.</exception>
    public static TopicRef<T> Define(
        [ConstantExpected] string pubSubName,
        [ConstantExpected] string topicName) =>
        new(pubSubName, topicName);
}

/// <summary>
/// Identifies a system-owned connection point and the Dapr binding transport used to
/// materialize it. Direction follows from <c>From</c> and <c>To</c> usage; the binding
/// component name is derived as <c>binding.&lt;connector-name&gt;</c>.
/// </summary>
public sealed record ConnectorRef
{
    /// <summary>The connector's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
    public string Name { get; }

    /// <summary>The local transport — the kind of Dapr binding the connector materializes as during F5 runs.</summary>
    public Transport Transport { get; }

    /// <summary>
    /// The transport shape used after deployment, or <see langword="null"/> when the local
    /// transport also applies to deployed environments.
    /// </summary>
    public Transport? DeployedTransport { get; init; }

    private ConnectorRef(string name, Transport transport)
    {
        Name = name;
        Transport = transport;
    }

    /// <summary>
    /// Declares a connector resolved to a transport — the form <c>intropy system create</c>
    /// emits for the default local-file resolution, where the transport's endpoint (e.g. a
    /// <see cref="FileTransport"/> folder) is the connection itself.
    /// </summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <param name="transport">The kind of Dapr binding the connector materializes as.</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define([ConstantExpected] string name, Transport transport)
    {
        ArgumentNullException.ThrowIfNull(transport);
        return new ConnectorRef(NameRules.RequireLabel(name, nameof(name)), transport);
    }

    /// <summary>
    /// Declares the value-free transport shape that materializes for deployment. Connection
    /// values remain environment-owned deployment configuration; local F5 runs keep using
    /// <see cref="Transport"/>.
    /// </summary>
    /// <param name="transport">The deployed Dapr binding transport shape.</param>
    /// <returns>A connector reference with the deployed transport set.</returns>
    public ConnectorRef WithDeployed(Transport transport)
    {
        ArgumentNullException.ThrowIfNull(transport);
        return this with { DeployedTransport = transport };
    }
}

/// <summary>
/// The kind of Dapr binding a connector materializes as. All connectivity goes through
/// Dapr — the transport selects the Dapr binding component's <c>spec.type</c>; it never
/// bypasses Dapr. The component name is always derived: <c>binding.&lt;connector-name&gt;</c>.
/// </summary>
[JsonPolymorphic(TypeDiscriminatorPropertyName = "$transport")]
[JsonDerivedType(typeof(FileTransport), "file")]
[JsonDerivedType(typeof(SftpTransport), "sftp")]
public abstract record Transport
{
    private protected Transport()
    {
    }

    /// <summary>The Dapr binding component's <c>spec.type</c> (e.g. <c>bindings.localstorage</c>).</summary>
    public abstract string DaprType { get; }

    /// <summary>Whether the transport can provide input to a component through <c>From</c>.</summary>
    [JsonIgnore]
    public abstract bool SupportsInput { get; }

    /// <summary>Whether the transport can accept component output through <c>To</c>.</summary>
    [JsonIgnore]
    public abstract bool SupportsOutput { get; }

    /// <summary>
    /// Local file transport (<c>bindings.localstorage</c>): reads and writes files in a folder on
    /// the host. The folder is the endpoint. This is the default resolution
    /// <c>intropy system create</c> applies.
    /// </summary>
    /// <param name="rootPath">The folder the binding reads and writes, relative to the SystemHost directory or absolute.</param>
    /// <exception cref="ArgumentException">The root path is null or whitespace.</exception>
    public static Transport File([ConstantExpected] string rootPath) => new FileTransport(rootPath);

    /// <summary>
    /// SFTP transport (<c>bindings.sftp</c>) for deployed environments. Its address,
    /// credentials, and path are supplied by deployment configuration.
    /// </summary>
    public static Transport Sftp() => new SftpTransport();
}

/// <summary>
/// Local file transport: a Dapr binding component of type <c>bindings.localstorage</c> rooted at
/// <see cref="RootPath"/>. The folder is the endpoint.
/// </summary>
public sealed record FileTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.localstorage";

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsInput => true;

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsOutput => true;

    /// <summary>The folder the binding reads and writes, relative to the SystemHost directory or absolute.</summary>
    public string RootPath { get; }

    /// <summary>Creates a local file transport. Prefer <see cref="Transport.File"/>.</summary>
    /// <param name="rootPath">The folder the binding reads and writes.</param>
    /// <exception cref="ArgumentException">The root path is null or whitespace.</exception>
    public FileTransport(string rootPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(rootPath);
        RootPath = rootPath;
    }
}

/// <summary>
/// Value-free SFTP output transport: a Dapr binding component of type <c>bindings.sftp</c>.
/// Deployment configuration supplies its address, credentials, and path.
/// </summary>
public sealed record SftpTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.sftp";

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsInput => false;

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsOutput => true;
}

using Intropy.Topology.Model;

namespace Intropy.Topology;

/// <summary>
/// Represents a declared topology component and its recorded edges. Declaration methods
/// record intent; <see cref="SystemBuilder.Build"/> performs completeness and
/// cross-component validation. Instances are mutable during declaration and not thread-safe.
/// </summary>
public abstract class Component
{
    /// <summary>The output port name recorded for every <c>Publishes</c> call.</summary>
    internal const string DefaultPort = "default";

    private readonly List<TopicRef> _subscribes = [];
    private readonly List<(string Port, TopicRef Topic)> _publishes = [];
    private readonly List<(ConnectorRef Connector, ConnectorDirection Direction)> _connectors = [];

    private protected Component(string name, ComponentKind kind)
    {
        Name = name;
        Kind = kind;
    }

    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public string Name { get; }

    /// <summary>The component's block kind.</summary>
    public ComponentKind Kind { get; }

    /// <summary>The cron schedule recorded by <c>WithSchedule</c>; null when the component
    /// runs once at host start. A later call replaces the value. Syntax is validated at
    /// <see cref="SystemBuilder.Build"/>.</summary>
    internal string? ScheduleCall { get; private set; }

    internal IReadOnlyList<TopicRef> SubscribeCalls => _subscribes;

    internal IReadOnlyList<(string Port, TopicRef Topic)> PublishCalls => _publishes;

    internal IReadOnlyList<(ConnectorRef Connector, ConnectorDirection Direction)> ConnectorCalls => _connectors;

    internal void AddSubscribe(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _subscribes.Add(topic);
    }

    internal void AddPublish(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _publishes.Add((DefaultPort, topic));
    }

    internal void AddConnector(ConnectorRef connector, ConnectorDirection direction)
    {
        ArgumentNullException.ThrowIfNull(connector);
        _connectors.Add((connector, direction));
    }

    internal void SetSchedule(string cron)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cron);
        ScheduleCall = cron;
    }
}

/// <summary>The declared extractor: an edge block that pulls or receives data from an
/// external system and publishes it. Obtained from the extractor builder's
/// <c>Component</c> property.</summary>
public sealed class ExtractorComponent : Component
{
    internal ExtractorComponent(string name) : base(name, ComponentKind.Extractor) { }
}

/// <summary>The declared loader: an edge block that consumes exactly one topic and writes
/// to an external system. Obtained from the loader builder's <c>Component</c> property.</summary>
public sealed class LoaderComponent : Component
{
    internal LoaderComponent(string name) : base(name, ComponentKind.Loader) { }
}

/// <summary>The declared transactional integration: a synchronous block that reads/writes
/// external systems through connectors. Obtained from the integration builder's
/// <c>Component</c> property.</summary>
public sealed class TransactionalIntegrationComponent : Component
{
    internal TransactionalIntegrationComponent(string name)
        : base(name, ComponentKind.TransactionalIntegration) { }
}

using Intropy.Topology.Building;
using Intropy.Topology.Model;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Entry point for declaring an integration system's topology. Add components, wire
/// them to topics and connectors, then call <see cref="Build"/> to materialize and
/// validate the immutable <see cref="SystemTopology"/>. Resources (topics, connectors)
/// materialize from usage — there is no <c>AddTopic</c>. Not thread-safe;
/// a second <see cref="Build"/> after further mutation reflects the mutations.
/// </summary>
public sealed class SystemBuilder
{
    private readonly List<Component> _components = [];

    /// <summary>The system's name (DNS-1123 label).</summary>
    public string SystemName { get; }

    private SystemBuilder(string systemName)
    {
        SystemName = systemName;
    }

    internal IReadOnlyList<Component> Components => _components;

    /// <summary>Creates a builder for a named system.</summary>
    /// <param name="systemName">The system's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static SystemBuilder Create(string systemName) =>
        new(NameRules.RequireLabel(systemName, nameof(systemName)));

    /// <summary>Adds an extractor: pulls data out of an external system and publishes it.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public ExtractorBuilder AddExtractor(string name) =>
        new(Register(new ExtractorComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a loader: consumes a topic and writes to an external system.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public LoaderBuilder AddLoader(string name) =>
        new(Register(new LoaderComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a transactional integration.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public TransactionalIntegrationBuilder AddTransactionalIntegration(string name) =>
        new(Register(new TransactionalIntegrationComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>
    /// Materializes and validates the topology. Throws when any error-severity
    /// violation exists, carrying every diagnostic found.
    /// </summary>
    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
    public SystemTopology Build() =>
        TryBuild(out var topology, out var diagnostics)
            ? topology!
            : throw new TopologyValidationException(diagnostics);

    /// <summary>Non-throwing <see cref="Build"/>: returns false with the diagnostics when the topology is invalid.</summary>
    /// <param name="topology">The topology when valid; null otherwise.</param>
    /// <param name="diagnostics">All diagnostics found, including warnings.</param>
    public bool TryBuild(out SystemTopology? topology, out IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        var candidate = TopologyMaterializer.Materialize(this);
        diagnostics = TopologyRules.Run(this, candidate);
        if (diagnostics.Any(d => d.Severity == DiagnosticSeverity.Error))
        {
            topology = null;
            return false;
        }

        topology = candidate;
        return true;
    }

    /// <summary>Runs validation without throwing; returns all diagnostics including warnings.</summary>
    public IReadOnlyList<TopologyDiagnostic> Validate() =>
        TopologyRules.Run(this, TopologyMaterializer.Materialize(this));

    private T Register<T>(T component) where T : Component
    {
        _components.Add(component);
        return component;
    }
}

using System.Reflection;
using Intropy.Topology.Model;

namespace Intropy.Topology;

/// <summary>
/// A discoverable system declaration. A system is a type implementing this interface; it names the
/// system and declares its topology into the supplied <see cref="SystemBuilder"/>.
/// <see cref="SystemDiscovery.Discover"/> finds, instantiates, and builds it.
/// </summary>
public interface ISystemDefinition
{
    /// <summary>The system's name (DNS-1123 label).</summary>
    string SystemName { get; }

    /// <summary>Declares the system's components and edges into <paramref name="builder"/>.</summary>
    /// <param name="builder">A builder created for <see cref="SystemName"/>.</param>
    void Define(SystemBuilder builder);
}

/// <summary>The result of discovering a system: its validated topology and the definition instance.</summary>
/// <param name="Topology">The materialized, validated topology.</param>
/// <param name="Definition">The definition instance (carries optional seams such as dev profiles).</param>
public sealed record DiscoveredSystem(SystemTopology Topology, ISystemDefinition Definition);

/// <summary>Discovers and builds the single <see cref="ISystemDefinition"/> declared in an assembly.</summary>
public static class SystemDiscovery
{
    /// <summary>
    /// Finds the one concrete <see cref="ISystemDefinition"/> in <paramref name="assembly"/>,
    /// instantiates it via its parameterless constructor, declares its topology, and validates it.
    /// </summary>
    /// <param name="assembly">The assembly to scan.</param>
    /// <returns>The validated topology and the definition instance.</returns>
    /// <exception cref="InvalidOperationException">No definition, or more than one, was found.</exception>
    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
    public static DiscoveredSystem Discover(Assembly assembly)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        return DiscoverFrom(assembly.GetName().Name ?? assembly.ToString(), assembly.GetTypes());
    }

    internal static DiscoveredSystem DiscoverFrom(string source, IReadOnlyList<Type> types)
    {
        var candidates = types
            .Where(t => t is { IsAbstract: false, IsInterface: false } && typeof(ISystemDefinition).IsAssignableFrom(t))
            .ToList();

        if (candidates.Count == 0)
        {
            throw new InvalidOperationException(
                $"No {nameof(ISystemDefinition)} was found in '{source}'.");
        }

        if (candidates.Count > 1)
        {
            throw new InvalidOperationException(
                $"Multiple {nameof(ISystemDefinition)} types were found in '{source}': " +
                $"{string.Join(", ", candidates.Select(t => t.FullName))}. Exactly one is required.");
        }

        var definition = (ISystemDefinition)Activator.CreateInstance(candidates[0])!;
        var builder = SystemBuilder.Create(definition.SystemName);
        definition.Define(builder);
        return new DiscoveredSystem(builder.Build(), definition);
    }
}

namespace Intropy.Topology;

/// <summary>How severe a topology diagnostic is.</summary>
public enum DiagnosticSeverity
{
    /// <summary>Suspicious but does not fail <see cref="SystemBuilder.Build"/>.</summary>
    Warning,

    /// <summary>Fails <see cref="SystemBuilder.Build"/>.</summary>
    Error,
}

/// <summary>One validation finding produced while building a topology.</summary>
/// <param name="Severity">The finding's severity.</param>
/// <param name="Message">A human-readable description of the violation.</param>
/// <param name="Target">The component or resource name the finding is about, when applicable.</param>
public sealed record TopologyDiagnostic(
    DiagnosticSeverity Severity,
    string Message,
    string? Target);

using System.Globalization;
using System.Text;

namespace Intropy.Topology;

/// <summary>
/// Thrown by <see cref="SystemBuilder.Build"/> when the declared topology has one or
/// more error-severity violations. Carries every diagnostic found — not just the first —
/// so a SystemHost run reports the whole picture at once.
/// </summary>
public sealed class TopologyValidationException : Exception
{
    /// <summary>All diagnostics found, including warnings.</summary>
    public IReadOnlyList<TopologyDiagnostic> Diagnostics { get; }

    /// <summary>Creates the exception with no diagnostics.</summary>
    public TopologyValidationException()
    {
        Diagnostics = [];
    }

    /// <summary>Creates the exception with a message and no diagnostics.</summary>
    /// <param name="message">The exception message.</param>
    public TopologyValidationException(string message)
        : base(message)
    {
        Diagnostics = [];
    }

    /// <summary>Creates the exception with a message, an inner exception, and no diagnostics.</summary>
    /// <param name="message">The exception message.</param>
    /// <param name="innerException">The causing exception.</param>
    public TopologyValidationException(string message, Exception innerException)
        : base(message, innerException)
    {
        Diagnostics = [];
    }

    /// <summary>Creates the exception from the full diagnostic list.</summary>
    /// <param name="diagnostics">All diagnostics found while validating the topology.</param>
    public TopologyValidationException(IReadOnlyList<TopologyDiagnostic> diagnostics)
        : base(BuildMessage(diagnostics))
    {
        Diagnostics = diagnostics;
    }

    private static string BuildMessage(IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        var errorCount = diagnostics.Count(d => d.Severity == DiagnosticSeverity.Error);
        var builder = new StringBuilder();
        builder.Append(CultureInfo.InvariantCulture, $"The system topology is invalid ({errorCount} error(s)):");
        foreach (var diagnostic in diagnostics)
        {
            builder.AppendLine();
            builder.Append(CultureInfo.InvariantCulture, $"  [{diagnostic.Severity}]");
            if (diagnostic.Target is not null)
            {
                builder.Append(CultureInfo.InvariantCulture, $" {diagnostic.Target}:");
            }

            builder.Append(CultureInfo.InvariantCulture, $" {diagnostic.Message}");
        }

        return builder.ToString();
    }
}

